func (t *Executor) destroyDirect(ctx context.Context, opts DestroyOptions) error {
  args := []string{"destroy"}
  args = append(args, t.buildVarArgs(opts.VarFile, nil)...)
  if opts.AutoApprove { args = append(args, "-auto-approve") }
  if opts.Parallelism > 0 { args = append(args, fmt.Sprintf("-parallelism=%d", opts.Parallelism)) }
  for _, target := range opts.Targets { args = append(args, "-target="+target) }
  return t.run(ctx, args...)
}
